Insert into CTMEDIA_LICENSE (MEDIA_LICENSE_ID,DISPLAY,DESCRIPTION,URI) values (1,'MCZ Permissions & Copyright','copyrighted material - All MCZ images and publications should have this designation','http://www.mcz.harvard.edu/collectionsoperations/permissions_copyright.html');
Insert into CTMEDIA_LICENSE (MEDIA_LICENSE_ID,DISPLAY,DESCRIPTION,URI) values (4,'Rights defined by 3rd party host','This material is hosted by an external party. Please refer to the licensing statement provided by the linked host.','#');
Insert into CTMEDIA_LICENSE (MEDIA_LICENSE_ID,DISPLAY,DESCRIPTION,URI) values (5,'Creative Commons Zero (CC0)','CC0 enables scientists, educators, artists and other creators and owners of copyright- or database-protected content to waive those interests in their works and thereby place them as completely as possible in the public domain.','https://creativecommons.org/publicdomain/zero/1.0/legalcode');
Insert into CTMEDIA_LICENSE (MEDIA_LICENSE_ID,DISPLAY,DESCRIPTION,URI) values (6,'Creative Commons Attribution (CC BY)','This license lets others distribute, remix, tweak, and build upon your work, even commercially, as long as they credit you for the original creation. ','https://creativecommons.org/licenses/by/4.0/legalcode');
Insert into CTMEDIA_LICENSE (MEDIA_LICENSE_ID,DISPLAY,DESCRIPTION,URI) values (7,'Creative Commons Attribution-ShareAlike (CC BY-SA)','This license lets others remix, tweak, and build upon your work even for commercial purposes, as long as they credit you and license their new creations under the identical terms. ','https://creativecommons.org/licenses/by-sa/4.0/legalcode');
Insert into CTMEDIA_LICENSE (MEDIA_LICENSE_ID,DISPLAY,DESCRIPTION,URI) values (8,'Creative Commons Attribution-NonCommercial (CC BY-NC)','This license lets others remix, tweak, and build upon your work non-commercially, and although their new works must also acknowledge you and be non-commercial, they don’t have to license their derivative works on the same terms.','https://creativecommons.org/licenses/by-nc/4.0/legalcode');
Insert into CTMEDIA_LICENSE (MEDIA_LICENSE_ID,DISPLAY,DESCRIPTION,URI) values (9,'Creative Commons Attribution-NonCommercial-ShareAlike (CC BY-NC-SA)','This license lets others remix, tweak, and build upon your work non-commercially, as long as they credit you and license their new creations under the identical terms.','https://creativecommons.org/licenses/by-nc-sa/4.0/legalcode');
